/* ---- GRAFICA DI PROVA: zattera d'arte + vento ---- */
GfxNew.raft=function(){
  const RA={};GfxNew.rart=RA;
  const ld=(b)=>{const i=new Image();i.src='data:image/webp;base64,'+b;return i};
  RA.hull=ld("");RA.mast=ld("");RA.sail=[ld(""),ld("")];
  const done=i=>i.complete&&i.naturalWidth>0;
  RA.ok=()=>done(RA.mast)&&done(RA.sail[0])&&done(RA.sail[1]);
  // scafo: stesso formato dello sprite originale (ombra sull'acqua + schiuma)
  const mkH=(fl)=>{const[c,x]=mk(150,92);const s={c,w:150,h:92,ax:75,ay:46,art:1,_x:x};
    const paint=()=>{x.clearRect(0,0,150,92);
      x.fillStyle='rgba(6,40,60,.28)';x.beginPath();x.ellipse(79,54,66,30,0,0,7);x.fill();
      x.save();x.strokeStyle='rgba(255,255,255,.30)';x.lineWidth=2.4;x.setLineDash([12,9]);x.beginPath();x.ellipse(75,46,69,37,0,0,7);x.stroke();x.restore();
      x.save();if(fl)x.filter=fl;x.drawImage(RA.hull,11,13,128,66);x.restore()};
    paint();if(!done(RA.hull))RA.hull.addEventListener('load',paint);return s};
  SP.raftHull=mkH();SP.raftHull2=mkH('brightness(.9) saturate(1.2) contrast(1.05)');
  // vento: direzione che deriva lentamente, forza con raffiche (più forte col maltempo)
  RA.wind=t=>{const a=.9+Math.sin(t*.021)*1.15+Math.sin(t*.053+1)*.5;
    const wi=(typeof WX!=='undefined'&&WX.i)||0;
    const s=Math.max(.2,Math.min(1.5,.55+.22*Math.sin(t*.07)+.18*Math.sin(t*.31)+.1*Math.sin(t*.9)+wi*.8));
    return{a,s}};
  // angolo di destinazione della vela: sottovento, mai dritta verso prua
  RA.tgt=(o,hd,t,nrm)=>{const w=RA.wind(t),d=nrm(w.a-(hd+Math.PI));
    let sg=d>=0?1:-1;if(Math.abs(d)<.15&&o.wsg)sg=o.wsg;o.wsg=sg;
    const m=Math.max(.25,Math.min(.8,Math.abs(d)*.45));
    const tgt=hd+Math.PI+sg*m,sn=Math.sin(w.a-tgt);
    if(Math.abs(sn)>.12)o.side=sn>0?1:-1;
    return tgt};
  // triangolo texturizzato
  const tri=(g,im,x0,y0,x1,y1,x2,y2,u0,v0,u1,v1,u2,v2,sh,hl)=>{
    const den=u0*(v1-v2)+u1*(v2-v0)+u2*(v0-v1);if(Math.abs(den)<1e-6)return;
    const cx=(x0+x1+x2)/3,cy=(y0+y1+y2)/3,ex=(a,b)=>{const dx=a-cx,dy=b-cy,l=Math.hypot(dx,dy)||1;return[a+dx/l*.7,b+dy/l*.7]};
    const A=ex(x0,y0),B=ex(x1,y1),C=ex(x2,y2);
    g.save();g.beginPath();g.moveTo(A[0],A[1]);g.lineTo(B[0],B[1]);g.lineTo(C[0],C[1]);g.closePath();g.clip();
    const a=(x0*(v1-v2)+x1*(v2-v0)+x2*(v0-v1))/den,b=(y0*(v1-v2)+y1*(v2-v0)+y2*(v0-v1))/den,
      c=(x0*(u2-u1)+x1*(u0-u2)+x2*(u1-u0))/den,d=(y0*(u2-u1)+y1*(u0-u2)+y2*(u1-u0))/den,
      e=(x0*(u1*v2-u2*v1)+x1*(u2*v0-u0*v2)+x2*(u0*v1-u1*v0))/den,f=(y0*(u1*v2-u2*v1)+y1*(u2*v0-u0*v2)+y2*(u0*v1-u1*v0))/den;
    g.transform(a,b,c,d,e,f);g.drawImage(im,0,0);if(!im._d){const sil=(col)=>{const c=document.createElement('canvas');c.width=im.naturalWidth;c.height=im.naturalHeight;const x=c.getContext('2d');x.drawImage(im,0,0);x.globalCompositeOperation='source-in';x.fillStyle=col;x.fillRect(0,0,c.width,c.height);return c};im._d=sil('#281a0c');im._l=sil('#fff6de')}
    if(sh>.01){g.globalAlpha=Math.min(1,sh);g.drawImage(im._d,0,0)}
    if(hl>.01){g.globalAlpha=Math.min(1,hl);g.drawImage(im._l,0,0)}
    g.restore()};
  const NU=9,NV=7;
  RA.draw=(g,mx,my,o,t,red)=>{
    const w=RA.wind(t),ws=w.s,a=o.a,ca=Math.cos(a),sa=Math.sin(a),dx=(ca<0?-1:1)*Math.max(.3,Math.abs(ca)),dy=(sa<0?-1:1)*Math.sqrt(1-dx*dx)*.5,flip=dx<0;
    const tb=o.side>=0?1:-1;o.bs=(o.bs===undefined?tb:o.bs)+(tb-(o.bs===undefined?tb:o.bs))*.1;
    const sd=o.bs,nx=-dy*2*sd*.5,ny=dx*.5*sd;
    const L=86,Z0=46,Z1=134,bil=(9+13*Math.min(ws,1.2))*(1+.13*Math.sin(t*(1.5+ws*2)));
    const fa=.8+2.6*ws,fs=2.6+3.4*ws;
    const im=RA.sail[red?1:0],iw=im.naturalWidth,ih=im.naturalHeight;
    const P=[],Q=[];
    for(let j=0;j<=NV;j++){const v=j/NV;for(let i=0;i<=NU;i++){const s=i/NU,u=s*L,z=Z1-(Z1-Z0)*v;
      const fv=.55+.45*Math.sin(Math.PI*(.08+.84*v)),sf=Math.pow(s,.85);
      const bb=sf*fv*bil+Math.sin(t*fs+s*3.4+v*2.2)*fa*sf*.8;
      const lift=-Math.abs(bb)*.08*v;
      P.push([mx+dx*u+nx*bb,my+dy*u+ny*bb-z+lift]);
      Q.push([s*iw,v*ih,bb])}}
    g.save();
    g.drawImage(RA.mast,mx-8.25,my-156,16.5,156);
    for(let j=0;j<NV;j++)for(let i=0;i<NU;i++){
      const k=j*(NU+1)+i,p00=P[k],p10=P[k+1],p01=P[k+NU+1],p11=P[k+NU+2],q00=Q[k],q10=Q[k+1],q01=Q[k+NU+1],q11=Q[k+NU+2];
      const sl=((q10[2]-q00[2])+(q01[2]-q00[2])*.4)*(sd>=0?1:-1),sh=Math.max(0,Math.min(.42,.12-sl*.045)),hl=Math.max(0,Math.min(.22,sl*.04-.02));
      tri(g,im,p00[0],p00[1],p10[0],p10[1],p01[0],p01[1],q00[0],q00[1],q10[0],q10[1],q01[0],q01[1],sh,hl);
      tri(g,im,p10[0],p10[1],p11[0],p11[1],p01[0],p01[1],q10[0],q10[1],q11[0],q11[1],q01[0],q01[1],sh,hl)}
    g.restore()};
};
